11. Adım: 
nano index.html komutuyla oluşturulan dosyaya aşağıdaki kodları girip Ctrl + O tuşuyla 
kaydediniz.
<!DOCTYPE html><html><head> <title>Canlı Sohbet</title></head> 
<body><h2>Canlı Mesajlaşma Uygulaması</h2> 
<input id=”msg” placeholder=”Mesaj yaz”> 
<button onclick=”send()”>Gönder</button> 
<ul id=”messages”></ul> 
<script src=”/socket.io/socket.io.js”></script> 
<script> 
const socket = io(); 
        function send() { 
            const msg = document.getElementById(“msg”).value; 
            socket.emit(“chat message”, msg); 
        }
        socket.on(“chat message”, function(msg) { 
            const li = document.createElement(“li”); 
            li.textContent = msg; 
            document.getElementById(“messages”).appendChild(li); 
        });
    </script></body></html>
